/* move a monster; if a threat to busy hero, stop doing whatever it is */
/**
 * @param {$T.monst | null} mtmp struct monst *
 * @param {number} chug boolean
 * @returns {Promise<number>} int
 */
export async function dochugw(mtmp, chug) {   // monmove.c:204
    /* True: monster is moving;
     * False: monster was just created or has teleported
     * so perform stop-what-you're-doing-if-close-enough-
     * to-be-a-threat check but don't move mtmp */
    const x = mtmp.mx;
    const y = mtmp.my;   /* 'mtmp's location before dochug() */
    /* skip canspotmon() if occupation is Null */
    const already_saw_mon = chug && go.occupation ? canspotmon(mtmp) : 0;
    const rd = chug ? await dochug(mtmp) : 0;
    /*
     * A similar check is in monster_nearby() in hack.c.
     * [The two checks have a lot of differences and chances are high
     * that some of those are unintentional.]
     */
    /* check whether hero notices monster and stops current activity */
    /* monster is hostile and can attack (or hallu distorts knowledge) */
    /* it's close enough to be a threat */
    /* and either couldn't see it before, or it was too far away */
    /* can see it now, or sense it and would normally see it */
    /* monster isn't paralyzed or afraid (scare monster/Elbereth) */
    if (go.occupation && !rd
        && (Hallucination() || !mtmp.mpeaceful && !noattacks(mtmp.data))
        && dist2(mtmp.mx, mtmp.my, u.ux, u.uy) <= (BOLT_LIM + 1) * (BOLT_LIM + 1)
        && (!already_saw_mon || !couldsee(x, y)
        || distu(x, y) > (BOLT_LIM + 1) * (BOLT_LIM + 1))
        && canspotmon(mtmp) && couldsee(mtmp.mx, mtmp.my)
        && mtmp.mcanmove && !onscary(u.ux, u.uy, mtmp)) {
        await stop_occupation();
    }
    return rd;
}
/**
 * @param {number} x coordxy
 * @param {number} y coordxy
 * @param {$T.monst | null} mtmp struct monst *
 * @returns {number} boolean
 */
export function onscary(x, y, mtmp) {   // monmove.c:241
    let ep = null;
    /* <0,0> is used by musical scaring;
     * it doesn't care about scrolls or engravings or dungeon branch */
    const auditory_scare = x === 0 && y === 0 ? 1 : 0;
    const magical_scare = !auditory_scare ? 1 : 0;
    /* creatures who are directly resistant to any type of scaring:
     * Rodney, lawful minions, Angels, the Riders */
    if (mtmp.iswiz || is_lminion(mtmp) || mtmp.data === mons[PM.ANGEL]
        || is_rider(mtmp.data)) {
        return FALSE;
    }
    /* creatures who are directly resistant to magical scaring
     * based on the mere presence of something at a location:
     * humans etc.
     * uniques have ascended their base monster instincts */
    if (magical_scare
        && (mtmp.data.mlet === S.HUMAN || unique_corpstat(mtmp.data))) {
        return FALSE;
    }
    /* creatues who resist scaring under particular circumstances:
     * shopkeepers inside their own shop
     * priests inside their own temple */
    if (mtmp.isshk && inhishop(mtmp)
        || mtmp.ispriest && inhistemple(mtmp)) {
        return FALSE;
    }
    if (auditory_scare) {
        return TRUE;
    }
    /* should this still be true for defiled/molochian altars? */
    if (svl.level.locations[x][y].typ === ALTAR
        && (mtmp.data.mlet === S.VAMPIRE || is_vampshifter(mtmp))) {
        return TRUE;
    }
    /* the scare monster scroll doesn't have any of the below
     * restrictions, being its own source of power */
    if (sobj_at(SCR_SCARE_MONSTER, x, y)) {
        return TRUE;
    }
    /*
     * Creatures who don't (or can't) fear a written Elbereth:
     * all the above plus shopkeepers (even if poly'd into non-human),
     * vault guards (also even if poly'd), blind or peaceful monsters,
     * humans and elves, and minotaurs.
     *
     * If the player isn't actually on the square OR the player's image
     * isn't displaced to the square, no protection is being granted.
     *
     * Elbereth doesn't work in Gehennom, the Elemental Planes, or the
     * Astral Plane; the influence of the Valar only reaches so far.
     */
    return (ep = sengr_at($C`Elbereth`, x, y, TRUE)) !== null
        && (u_at(x, y)
        || Displaced() && mtmp.mux === x && mtmp.muy === y
        || ep.guardobjects && vobj_at(x, y))
        && !(mtmp.isshk || mtmp.isgd || !mtmp.mcansee
        || mtmp.mpeaceful
        || mtmp.data === mons[PM.MINOTAUR]
        || Inhell() || In_endgame(u.uz)) ? 1 : 0;
}
/* regenerate lost hit points */
/**
 * @param {$T.monst | null} mon struct monst *
 * @param {number} digest_meal boolean
 * @returns {Promise<void>}
 */
export async function mon_regen(mon, digest_meal) {   // monmove.c:307
    if ($c.rem64(svm.moves, 20) === 0 || regenerates(mon.data)) {
        await healmon(mon, 1, 0);
    }
    if (mon.mspec_used) {
        mon.mspec_used = mon.mspec_used - 1 | 0;
    }
    if (digest_meal) {
        if (mon.meating) {
            mon.meating = mon.meating - 1 | 0;
            if (mon.meating <= 0) {
                await finish_meating(mon);
            }
        }
    }
}
/*
 * Possibly awaken the given monster.  Return a 1 if the monster has been
 * jolted awake.
 */
/**
 * @param {$T.monst | null} mtmp struct monst *
 * @returns {Promise<number>} int
 */
async function disturb(mtmp) {   // monmove.c:327
    /*
     * + Ettins are hard to surprise.
     * + Nymphs, jabberwocks, and leprechauns do not easily wake up.
     *
     * Wake up if:
     *  in direct LOS                                           AND
     *  within 10 squares                                       AND
     *  not stealthy or (mon is an ettin and 9/10)              AND
     *  (mon is not a nymph, jabberwock, or leprechaun) or 1/50 AND
     *  Aggravate or mon is (dog or human) or
     *      (1/7 and mon is not mimicking furniture or object)
     */
    /* DEFERRED */
    if (couldsee(mtmp.mx, mtmp.my) && dist2(mtmp.mx, mtmp.my, u.ux, u.uy) <= 100
        && (!Stealth() || mtmp.data === mons[PM.ETTIN] && rn2(10))
        && (!(mtmp.data.mlet === S.NYMPH
        || mtmp.data === mons[PM.JABBERWOCK]
        || mtmp.data.mlet === S.LEPRECHAUN) || !rn2(50))
        && (Aggravate_monster()
        || (mtmp.data.mlet === S.DOG || mtmp.data.mlet === S.HUMAN)
        || !rn2(7) && M_AP_TYPE(mtmp) !== M_AP.FURNITURE
        && M_AP_TYPE(mtmp) !== M_AP.OBJECT)) {
        await wake_msg(mtmp, !mtmp.mpeaceful ? 1 : 0);
        mtmp.msleeping = 0;
        return 1;
    }
    return 0;
}
